from moler.device.unixremote import UnixRemote


class NokiaUnixRemote(UnixRemote):
    """UnixRemote with specific Nokia commands and events."""

    _supported_states = (UnixRemote.unix_remote, UnixRemote.unix_remote_root, UnixRemote.proxy_pc, UnixRemote.unix_local, UnixRemote.unix_local_root)

    def _get_packages_for_state(self, state, observer):
        """
        Get available packages contain cmds and events for each state.

        :param state: device state.
        :param observer: observer type, available: cmd, events
        :return: available cmds or events for specific device state.
        """
        if state in NokiaUnixRemote._supported_states:
            available = {
                NokiaUnixRemote.cmds: ["moler.cmd.unix", "ta_moler.cmd.shared.nokiaunix"],
                NokiaUnixRemote.events: ["moler.events.shared", "moler.events.unix"],
            }
            return available[observer]
        return []
